import{c as r,Q as o,J as s,h as n,e,l,m as i,k as c}from"./chunks/framework.NhpCCunm.js";const x=JSON.parse('{"title":"Online Candle & Soap Cost Calculator: Wax, Fragrance & Jars","description":"Free online candle and artisan soap cost calculator for craft makers. Calculate soy wax grams, fragrance oil load %, crackling wicks, amber jars, and craft labor.","frontmatter":{"title":"Online Candle & Soap Cost Calculator: Wax, Fragrance & Jars","description":"Free online candle and artisan soap cost calculator for craft makers. Calculate soy wax grams, fragrance oil load %, crackling wicks, amber jars, and craft labor.","tags":["Tools","Economics","Crafts & Handmade"],"head":[["script",{"type":"application/ld+json"},"{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"@type\\": \\"WebApplication\\",\\n  \\"name\\": \\"Online Candle & Soap Cost Calculator\\",\\n  \\"applicationCategory\\": \\"BusinessApplication\\",\\n  \\"operatingSystem\\": \\"All\\",\\n  \\"browserRequirements\\": \\"Requires JavaScript. Requires HTML5.\\",\\n  \\"offers\\": {\\n    \\"@type\\": \\"Offer\\",\\n    \\"price\\": \\"0\\",\\n    \\"priceCurrency\\": \\"USD\\"\\n  },\\n  \\"description\\": \\"Free online candle and artisan soap cost calculator for craft makers. Calculate soy wax grams, fragrance oil load %, crackling wicks, amber jars, and craft labor.\\"\\n}\\n"]]},"headers":[],"relativePath":"calculators/candle-cost-calculator.md","filePath":"calculators/candle-cost-calculator.md"}'),d={name:"calculators/candle-cost-calculator.md"};function p(h,a,g,u,f,m){const t=o("CostCalculator");return s(),n("div",null,[a[0]||(a[0]=e("div",{class:"article-breadcrumb"},[e("a",{href:"/calculators/"},"← All Calculators")],-1)),a[1]||(a[1]=e("h1",{id:"online-candle-soap-cost-calculator-soy-wax-fragrance-load-wicks-glassware",tabindex:"-1"},[l("Online Candle & Soap Cost Calculator: Soy Wax, Fragrance Load, Wicks & Glassware "),e("a",{class:"header-anchor",href:"#online-candle-soap-cost-calculator-soy-wax-fragrance-load-wicks-glassware","aria-label":'Permalink to "Online Candle & Soap Cost Calculator: Soy Wax, Fragrance Load, Wicks & Glassware"'},"​")],-1)),a[2]||(a[2]=e("p",null,"A free interactive online cost calculator for artisan candle makers, home soap crafters, and diffuser studios. Accurately calculate raw wax consumption, fragrance load percentages, wood wicks, amber glassware, rigid gift packaging, and your studio labor in under a minute.",-1)),i(t,{lang:"en",preset:"candle"}),a[3]||(a[3]=c('<div class="satellites-nav-block"><div class="satellites-nav-title"><svg class="satellite-title-icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="2" width="16" height="20" rx="2"></rect><line x1="8" y1="6" x2="16" y2="6"></line><line x1="16" y1="14" x2="16" y2="18"></line><path d="M16 10h.01"></path><path d="M12 10h.01"></path><path d="M8 10h.01"></path><path d="M12 14h.01"></path><path d="M8 14h.01"></path><path d="M12 18h.01"></path><path d="M8 18h.01"></path></svg><span>Other Cost Calculators:</span></div><div class="satellites-nav-grid"><a href="/calculators/leather-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"></rect><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"></path></svg></span><div class="satellite-info"><strong>Leathercraft Cost Calculator</strong><span>Usable hide area, cutting offcuts, hardware, and saddle stitch labor</span></div><span class="satellite-arrow">→</span></a><a href="/calculators/product-cost-calculator" class="satellite-nav-card"><span class="satellite-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg></span><div class="satellite-info"><strong>Universal Product Cost Calculator</strong><span>For any batch or custom manufactured item: materials, scrap, BOM, and labor</span></div><span class="satellite-arrow">→</span></a></div></div><hr><h2 id="candle-soap-economics-4-cost-traps-for-craft-makers" tabindex="-1">Candle &amp; Soap Economics: 4 Cost Traps for Craft Makers <a class="header-anchor" href="#candle-soap-economics-4-cost-traps-for-craft-makers" aria-label="Permalink to &quot;Candle &amp; Soap Economics: 4 Cost Traps for Craft Makers&quot;">​</a></h2><p>Candle making seems deceptive in its simplicity: melt soy wax flakes, stir in fragrance oil, pour into a lidded glass jar with a centered wick, and mark it up by 300%. Yet when makers audit their end-of-year accounts, packaging, marketplace seller fees, and expensive fragrance loss often consume all net profit.</p><p>Here are the four key overhead factors every artisan must track:</p><h3 id="_1-jar-fluid-volume-vs-net-wax-weight" tabindex="-1">1. Jar Fluid Volume vs Net Wax Weight <a class="header-anchor" href="#_1-jar-fluid-volume-vs-net-wax-weight" aria-label="Permalink to &quot;1. Jar Fluid Volume vs Net Wax Weight&quot;">​</a></h3><p>The specific gravity of melted natural wax is lower than water (approx. <strong>0.86–0.90 g/ml</strong>):</p><ul><li>A vessel rated at &quot;200 ml&quot; does not hold 200 grams of wax. It typically accommodates only <strong>160 to 170 grams</strong> of blended wax and fragrance.</li><li>Purchasing wax assuming 1:1 weight-to-volume ties up working capital in unsold inventory.</li><li>Across a 50-candle batch, miscalculating wax density leads to purchasing 1.5–2 kg of excess raw material.</li></ul><h3 id="_2-fragrance-oil-load-the-highest-single-expense" tabindex="-1">2. Fragrance Oil Load (The Highest Single Expense) <a class="header-anchor" href="#_2-fragrance-oil-load-the-highest-single-expense" aria-label="Permalink to &quot;2. Fragrance Oil Load (The Highest Single Expense)&quot;">​</a></h3><p>Premium fragrance oils (CandleScience, Makesy, French perfumeries) constitute <strong>35% to 50% of direct production costs</strong>:</p><ul><li><strong>Standard Fragrance Load:</strong> For maximum hot and cold scent throw, recipes call for <strong>8% to 10%</strong> fragrance oil calculated strictly against the weight of the wax.</li><li>A 160 g candle requires <strong>16 g of concentrated scent oil</strong>. At wholesale prices of $30–$40 per 16 oz, scent alone costs <strong>$1.80 to $2.50 per unit</strong>.</li><li>Overheating wax during fragrance addition flashes off delicate volatile top notes, wasting expensive aroma oil.</li></ul><h3 id="_3-pitcher-residue-and-thermal-shrinkage-8–12" tabindex="-1">3. Pitcher Residue and Thermal Shrinkage (8–12%) <a class="header-anchor" href="#_3-pitcher-residue-and-thermal-shrinkage-8–12" aria-label="Permalink to &quot;3. Pitcher Residue and Thermal Shrinkage (8–12%)&quot;">​</a></h3><p>Molten wax cannot be fully poured without leaving residue behind:</p><ul><li><strong>Pitcher Cling:</strong> 10 to 20 grams of wax inevitably solidifies against the walls and base of the melting pitcher per pour batch.</li><li><strong>Cooling Cavities &amp; Sinkholes:</strong> Soy and coconut waxes shrink as they cool. Surface sinkholes around the wick require secondary top-offs or heat gun remediation.</li><li><strong>Frosting &amp; Adhesion Pull-away:</strong> Drafts cause polymorphic crystallization (&quot;frosting&quot;), downgrading aesthetic candle grades.</li></ul><p>Production scrap allowances for wax must be set to <strong>at least 8%</strong>.</p><h3 id="_4-glassware-safety-compliance-and-gift-packaging" tabindex="-1">4. Glassware, Safety Compliance, and Gift Packaging <a class="header-anchor" href="#_4-glassware-safety-compliance-and-gift-packaging" aria-label="Permalink to &quot;4. Glassware, Safety Compliance, and Gift Packaging&quot;">​</a></h3><p>A premium artisanal candle is an assembly of fragile components:</p><ol><li><strong>UV-Blocking Amber Glass Jar &amp; Lid:</strong> Protects volatile essential oils from sunlight degradation ($1.20–$1.80).</li><li><strong>Crackling Wooden Wick &amp; Metal Anchor Clip:</strong> Delivers an ambient fireplace aesthetic ($0.30–$0.50).</li><li><strong>High-Temp Wick Adhesive Dot:</strong> Keeps the wick firmly anchored during hot pours ($0.15).</li><li><strong>Mandatory Safety Caution Label:</strong> Underwriters Laboratories / fire safety compliance icon sticker for the jar base ($0.15).</li><li><strong>Rigid Presentation Tube or Gift Box:</strong> Prevents shipping breakage during postal transport ($1.00–$1.50).</li></ol><hr><h2 id="unit-candle-cost-formula" tabindex="-1">Unit Candle Cost Formula <a class="header-anchor" href="#unit-candle-cost-formula" aria-label="Permalink to &quot;Unit Candle Cost Formula&quot;">​</a></h2><p>$$\\text{Unit Cost} = (W_{\\text{wax}} \\times 1.08 \\times P_{\\text{wax}}) + (W_{\\text{oil}} \\times P_{\\text{oil}}) + P_{\\text{jar}} + P_{\\text{wick}} + P_{\\text{packaging}} + (T_{\\text{labor}} \\times \\text{Wage}) + \\text{Equipment Wear}$$</p><hr><div class="cta-erp-box"><div class="cta-erp-content"><h3>Tired of recalculating scent loads and wax batches on scraps of paper?</h3><p>OmniCraft ERP is a local-first software built for craft studios. Store proprietary candle recipes with exact fragrance ratios, track expensive perfume oils and soy wax inventory by moving average cost (MAC), automatically deduct jars and wicks, and analyze actual batch margins offline.</p><a href="/" class="vp-button brand" data-omni-event="candle_article_cta_home_en"> Try OmniCraft ERP Free → </a></div></div>',23))])}const k=r(d,[["render",p]]);export{x as __pageData,k as default};
